Part.Source:
&Title = 'Relatório de Distribuição de Produtos por Rota' &AppName = 'Sistema de Gestão de Alimentação Escolar' &numeroLinha = 0 &Page = 0 &distItemProduto = 0 &totprodQtde = 0 &totprodQtdePeso = 0 &TotGeralQtdade = 0 &TotGeralPeso = 0 &totalQuantidade = 0
LoadWWPContext.Call(&WWPContext) &prefCodigo = &WWPContext.prefCodigo &itens.FromJson(&WWPContext.sdtprodutos.ToJson())
for &item in &itens if &item.check &prodCodigo += '[' + &item.prodCodigo.ToString().Trim() + ']' endif endfor
For each trnsdistribuicao, trnsdistribuicaoitens, trnsrota order prefCodigo, distItemProdutoDescricao, distRotaCodigo where prefCodigo = &prefCodigo where distDataEnvio >= &dataIncial where distDataEnvio <= &dataFinal where strSearch(&prodCodigo, '[' + distItemProduto.ToString().Trim() + ']', 1) > 0 where distRotaCodigo = &RotaCodigo when &RotaCodigo <> 0 where rotaCodigo = distRotaCodigo where distStatus = 'A' where rotaStatus = 'A'
Do 'Cabecalho' &imprimir = true
// Detecta mudança de produto if &distItemProduto <> distItemProduto if &distItemProduto <> 0
// Imprime total do produto anterior antes de mudar print printTotaisRotaProduto &numeroLinha += 1
print printTotalProduto &numeroLinha += 1
// Reseta totais do produto &totprodQtde = 0 &totprodQtdePeso = 0 &imprimir = false Do 'Cabecalho' endif
// Imprime os dados do novo produto print printDados &numeroLinha += 1 Do 'Cabecalho'
&distItemProduto = distItemProduto // Atualiza o produto atual endif
// Acumula quantidades por produtos &totprodQtde += distItemQuantidade &totprodQtdePeso += distItemProdutoPesoTotal
// Acumula quantidades para total Geral &TotGeralQtdade += distItemQuantidade &TotGeralPeso += distItemProdutoPesoTotal
// Lógica de controle por rota if ( &rotaCodigo = rotaCodigo and &imprimir ) or &rotaCodigo = 0 if &rotaCodigo = 0 &rotaCodigo = rotaCodigo &rotaDescricao = rotaDescricao &unidSigla = PRCDBuscarDescricaoSiglaOuUnidade(&prefCodigo, distItemProdutoUN, 'S') &pesoProduto = distItemProdutoPeso.ToString() + ' ' + distItemProdutoUNPeso &unidSiglaPeso = distItemProdutoUNPeso endif &distItemQuantidade += distItemQuantidade // Mantém a quantidade do item atual &distItemPesoTotal += distItemProdutoPesoTotal else // Imprime totais por rota antes de mudar if &imprimir print printTotaisRotaProduto &numeroLinha += 1 Do 'Cabecalho' endif
&rotaCodigo = rotaCodigo &rotaDescricao = rotaDescricao &unidSigla = PRCDBuscarDescricaoSiglaOuUnidade(&prefCodigo, distItemProdutoUN, 'S') &pesoProduto = distItemProdutoPeso.ToString() + ' ' + distItemProdutoUNPeso &unidSiglaPeso = distItemProdutoUNPeso &distItemQuantidade = distItemQuantidade &distItemPesoTotal = distItemProdutoPesoTotal endif
endfor
// Imprime o total do último produto, se houver if &distItemProduto <> 0 and &totprodQtde <> 0 print printTotaisRotaProduto print printTotalProduto &numeroLinha += 1 Do 'Cabecalho' endif
// Imprime o total geral, se houver if &TotGeralQtdade <> 0 print TotalGeral &numeroLinha += 1 Do 'Cabecalho' endif
sub 'Cabecalho' if &numeroLinha = 0 or &numeroLinha >= 20 For each where prefCodigo = &prefCodigo &prefLogo = prefLogo print printCabecalho print printCabecalhoDados endfor &numeroLinha = 1 endif endsub
